package ru.murad.yourmarket.service.impl;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import ru.murad.yourmarket.dto.response.AdvertisementResponseDto;import ru.murad.yourmarket.service.*;import ru.murad.yourmarket.telegram.TelegramGateway;import java.util.*;
@Service @RequiredArgsConstructor public class ModerationServiceImpl implements ModerationService {private final ModerationTransactionService transactions;private final AdvertisementPublicationService publication;private final TelegramGateway telegram;
@Override public Integer submit(UUID id){var claim=transactions.claimSubmission(id);if(!claim.sendAllowed())return claim.existingMessageId();try{transactions.markCallStarted(id,claim.operationId());List<Integer> media=telegram.sendModerationMedia(claim.advertisement());transactions.saveModerationMedia(id,claim.operationId(),media);transactions.markCallStarted(id,claim.operationId());Integer action=telegram.sendModerationAction(claim.advertisement());transactions.completeSubmission(id,claim.operationId(),action);return action;}catch(RuntimeException ex){try{transactions.markSubmissionUnknown(id,claim.operationId());}catch(RuntimeException mark){ex.addSuppressed(mark);}throw ex;}}
@Override public AdvertisementResponseDto approve(UUID id,Long admin){transactions.approve(id,admin);return publication.publish(id);}@Override public AdvertisementResponseDto reject(UUID id,Long admin,String reason){return transactions.reject(id,admin,reason);}}
